command:
cd /testbed && for py in /usr/bin/python3 /usr/bin/python3.10 /opt/miniconda3/bin/python; do echo "--- $py ---"; "$py" -V 2>&1; "$py" - <<'PY' 2>&1
mods = ['django', 'asgiref', 'sqlparse', 'pytz']
for m in mods:
    try:
        mod = __import__(m)
        print(m, getattr(mod, '__version__', 'installed'), getattr(mod, '__file__', ''))
    except Exception as e:
        print(m, 'MISSING', repr(e))
PY
done && printf '\n--- pip metadata ---\n' && find / -maxdepth 8 \( -iname 'asgiref-*.dist-info' -o -iname 'sqlparse-*.dist-info' -o -iname 'Django-*.dist-info' \) 2>/dev/null | head -50
